async def _count_members_fast(tenant_cfg: Dict[str, Any], group_id: str) -> int:
    """Lightweight member count via Graph $count (does not download the
    member list itself). Requires the ConsistencyLevel: eventual header."""
    try:
        token = await acquire_token(tenant_cfg)
        headers = {"Authorization": f"Bearer {token}", "ConsistencyLevel": "eventual"}
        url = f"{GRAPH_BASE}/groups/{group_id}/members/$count"
        async with httpx.AsyncClient(timeout=15.0) as client:
            resp = await client.get(url, headers=headers)
        if resp.status_code >= 400:
            return 0
        return int(resp.text)
    except Exception:
        return 0


async def list_group_members(tenant_cfg: Dict[str, Any], group_id: str) -> List[Dict[str, Any]]:
    """Fetch real member display names and emails for a group or distribution list."""
    if not _is_configured(tenant_cfg):
        return []
    try:
        members = await _paginate(
            f"{GRAPH_BASE}/groups/{group_id}/members?$select=id,displayName,mail,userPrincipalName&$top=999",
            tenant_cfg, 5000,
        )
        return [
            {"id": m.get("id", ""), "display_name": m.get("displayName", ""),
             "email": m.get("mail") or m.get("userPrincipalName", "")}
            for m in members
        ]
    except Exception:
        return []


async def discover_groups(tenant_cfg: Dict[str, Any]) -> List[Dict[str, Any]]:
    if not _is_configured(tenant_cfg):
        return _sim("groups")
    url = f"{GRAPH_BASE}/groups?$select=id,displayName,mail,groupTypes&$top=100"
    groups = await _paginate(url, tenant_cfg, 500)

    semaphore = asyncio.Semaphore(15)

    async def count_with_limit(gid):
        async with semaphore:
            return await _count_members_fast(tenant_cfg, gid)

    counts = await asyncio.gather(*[count_with_limit(g["id"]) for g in groups])

    return [
        {"id": g["id"], "display_name": g.get("displayName", ""),
         "primary_smtp": g.get("mail", ""), "member_count": counts[i],
         "group_type": ",".join(g.get("groupTypes", [])) or "Security"}
        for i, g in enumerate(groups)
    ]


async def discover_distribution_lists(tenant_cfg: Dict[str, Any]) -> List[Dict[str, Any]]:
    if not _is_configured(tenant_cfg):
        return _sim("distribution_lists")
    url = f"{GRAPH_BASE}/groups?$filter=mailEnabled eq true and securityEnabled eq false&$select=id,displayName,mail&$top=100"
    dls = await _paginate(url, tenant_cfg, 500)

    semaphore = asyncio.Semaphore(15)

    async def count_with_limit(gid):
        async with semaphore:
            return await _count_members_fast(tenant_cfg, gid)

    counts = await asyncio.gather(*[count_with_limit(d["id"]) for d in dls])

    return [
        {"id": d["id"], "display_name": d.get("displayName", ""),
         "primary_smtp": d.get("mail", ""), "member_count": counts[i]}
        for i, d in enumerate(dls)
    ]


async def _count_channels_fast(tenant_cfg: Dict[str, Any], team_id: str) -> int:
    # Note: /teams/{id}/channels does not support $select or $top - Graph
    # rejects those with a 400. Fetch plain and count locally instead.
    try:
        data = await _graph_request("GET", f"{GRAPH_BASE}/teams/{team_id}/channels", tenant_cfg)
        return len(data.get("value", []))
    except Exception:
        return 0


async def discover_teams(tenant_cfg: Dict[str, Any]) -> List[Dict[str, Any]]:
    if not _is_configured(tenant_cfg):
        return _sim("teams")
    data = await _graph_request("GET", f"{GRAPH_BASE}/teams", tenant_cfg)
    teams = data.get("value", [])

    semaphore = asyncio.Semaphore(15)

    async def counts_with_limit(team_id):
        async with semaphore:
            members = await _count_members_fast(tenant_cfg, team_id)
            channels = await _count_channels_fast(tenant_cfg, team_id)
            return members, channels

    results = await asyncio.gather(*[counts_with_limit(t["id"]) for t in teams])

    return [
        {"id": t["id"], "display_name": t.get("displayName", ""),
         "member_count": results[i][0], "channel_count": results[i][1],
         "visibility": t.get("visibility", "Private")}
        for i, t in enumerate(teams)
    ]


async def discover_contacts(tenant_cfg: Dict[str, Any]) -> List[Dict[str, Any]]:
    # Organizational contacts require Contacts.Read scope. Fall back to sim if not present.
    if not _is_configured(tenant_cfg):
        return _sim("contacts")
    try:
        contacts = await _paginate(f"{GRAPH_BASE}/contacts?$top=100&$select=id,displayName,mail,companyName", tenant_cfg, limit=5000)
        return [
            {"id": c["id"], "display_name": c.get("displayName", ""),
             "email": (c.get("mail") or ""), "company": c.get("companyName", "")}
            for c in contacts
        ]
    except GraphError:
        return _sim("contacts")


